import os
from pathlib import Path
from typing import IO, Any

from thirdparty.build import build_jobs, cmd_args_to_string
from thirdparty.cmake.presets import load_cmake_presets
from thirdparty.cmake.utils import is_multi_configuration
from thirdparty.errors import RecipeException
from thirdparty.files import chdir, mkdir
from thirdparty.msbuild.build import msbuild_verbosity_cmd_line_arg
from thirdparty.recipe import RecipeBase
from thirdparty.shell import run


def _cmake_cmd_line_args(recipe: RecipeBase, generator: str | None) -> list[str]:
    args: list[str] = []
    if not generator:
        return args

    # Arguments related to parallel
    njobs = build_jobs(recipe)
    if njobs and ("Makefiles" in generator or "Ninja" in generator) and "NMake" not in generator:
        args.append(f"-j{njobs}")

    maxcpucount = recipe.conf.tools.msbuild.max_cpu_count
    if maxcpucount is not None and "Visual Studio" in generator:
        args.append(f"/m:{maxcpucount}" if maxcpucount > 0 else "/m")

    # Arguments for verbosity
    if "Visual Studio" in generator:
        verbosity = msbuild_verbosity_cmd_line_arg(recipe)
        if verbosity:
            # trying to avoid issues with powershell and - : characters preceded by --
            # -verbosity -> /verbosity
            # https://github.com/PowerShell/PowerShell/issues/17399
            if recipe.conf.tools.env.virtualenv.powershell:
                verbosity = verbosity.replace("-", "/", 1)
            args.append(verbosity)

    return args


class CMake:
    """ CMake helper to use together with the CMakeToolchain feature """

    _recipe: RecipeBase
    _generator: str | None
    _toolchain_file: str | None
    _cache_variables: dict[str, Any]
    _cmake_program: str

    def __init__(self, recipe: RecipeBase):
        """
        :param recipe: The current recipe object. Always use ``self``.
        """
        # Store a reference to useful data
        self._recipe = recipe

        cmake_presets = load_cmake_presets(os.fspath(recipe.folders.generators))
        # Recipe generated presets will have exactly 1 configurePresets, no more
        configure_preset = cmake_presets["configurePresets"][0]

        self._generator = configure_preset["generator"]
        self._toolchain_file = configure_preset.get("toolchainFile")
        self._cache_variables = configure_preset["cacheVariables"]

        self._cmake_program = str(recipe.conf.tools.cmake.cmake_program or "cmake")

    @property
    def is_multi_configuration(self) -> bool:
        return is_multi_configuration(self._generator)

    def configure(
        self,
        variables: dict[str, Any] | None = None,
        build_script_folder: Path | None = None,
        cli_args: list[str] | None = None,
        stdout: IO[Any] | None = None,
        stderr: IO[Any] | None = None,
        subfolder: Path | None = None):
        """

        Reads the ``CMakePresets.json`` file generated by the
        :ref:`CMakeToolchain<recipe-cmake-toolchain>` to get:

           - The generator, to append ``-G="xxx"``.
           - Toolchain path to append ``-DCMAKE_TOOLCHAIN_FILE=/path/recipe_toolchain.cmake``
           - The declared ``cache variables`` to append ``-Dxxx``.

        and call ``cmake``.

        :param variables: Should be a dictionary of CMake variables and values, that will be mapped
                          to command line ``-DVAR=VALUE`` arguments.
                          Recall that in the general case information to CMake should be passed in
                          ``CMakeToolchain`` to be provided in the ``recipe_toolchain.cmake`` file.
                          This ``variables`` argument is intended for exceptional cases that wouldn't
                          work in the toolchain approach.
        :param build_script_folder: Path to the CMakeLists.txt in case it is not in the declared
                                    ``self.folders.source`` at the ``layout()`` method.
        :param cli_args: List of arguments ``[arg1, arg2, ...]`` that will be passed
                         as extra CLI arguments to pass to cmake invocation
        :param subfolder: (Experimental): subfolder to be created inside the ``build_folder`` and
                                          the ``package_folder``. If not provided, files will be
                                          placed in the ``build_folder`` and ``package_folder`` root.
        :param stdout: Use it to redirect stdout to this stream
        :param stderr: Use it to redirect stderr to this stream
        """
        self._recipe.output.info("Running CMake.configure()")
        cmakelist_folder = self._recipe.folders.source
        if build_script_folder:
            cmakelist_folder = cmakelist_folder / build_script_folder
        cmakelist_folder = cmakelist_folder.as_posix()

        build_folder = self._recipe.folders.build
        if subfolder:
            build_folder = build_folder / subfolder
        mkdir(self._recipe, build_folder)

        arg_list = [self._cmake_program]
        if self._generator:
            arg_list.append(f'-G "{self._generator}"')
        if self._toolchain_file:
            toolpath = self._toolchain_file
            if subfolder:
                toolpath = os.path.relpath(self._toolchain_file, start=subfolder)
            toolpath = toolpath.replace("\\", "/")
            arg_list.append(f'-DCMAKE_TOOLCHAIN_FILE="{toolpath}"')
        if self._recipe.folders.package:
            pkg_folder = self._recipe.folders.package.as_posix()
            arg_list.append(f'-DCMAKE_INSTALL_PREFIX="{pkg_folder}"')

        if not variables:
            variables = {}
        self._cache_variables.update(variables)

        arg_list.extend([f'-D{k}="{v}"' for k, v in self._cache_variables.items()])

        arg_list.append(f'"{cmakelist_folder}"')

        extra_args = self._recipe.conf.tools.cmake.configure_args
        arg_list.extend(extra_args)

        if not cli_args or ("--log-level" not in cli_args and "--loglevel" not in cli_args):
            arg_list.extend(self._cmake_log_levels_args)

        if cli_args:
            arg_list.extend(cli_args)

        command = " ".join(arg_list)
        with chdir(self._recipe, build_folder):
            run(self._recipe, command, stdout=stdout, stderr=stderr)

    def _config_arg(self, build_type: str | None) -> str:
        """ computes the '--config Release' arg when necessary, or warn or error if wrong
        """
        is_multi = is_multi_configuration(self._generator)
        if build_type and not is_multi:
            self._recipe.output.error(
                "Don't specify 'build_type' at build time for "
                "single-config build systems")
        if not build_type:
            try:
                build_type = self._recipe.settings.build_type  # declared, but can be None
                if not build_type:
                    raise RecipeException("CMake: build_type setting should be defined.")
            except RecipeException:
                if is_multi:
                    raise RecipeException("CMake: build_type setting should be defined.")
        build_config = f"--config {build_type}" if build_type and is_multi else ""
        return build_config

    def _build(
        self,
        build_type: str | None = None,
        target: str | list[str] | None = None,
        cli_args: list[str] | None = None,
        build_tool_args: list[str] | None = None,
        env: str | list[str] = "",
        stdout: IO[Any] | None = None,
        stderr: IO[Any] | None = None,
        subfolder: str | None = None):
        bf = self._recipe.folders.build
        if subfolder:
            bf = os.path.join(self._recipe.folders.build, subfolder)
        build_config = self._config_arg(build_type)

        args: list[Any] = []
        if target is not None:
            target_list = [target] if isinstance(target, str) else target
            args.extend(["--target"] + target_list)

        if cli_args:
            args.extend(cli_args)

        cmd_line_args = _cmake_cmd_line_args(self._recipe, self._generator)
        if build_tool_args:
            cmd_line_args.extend(build_tool_args)

        args.extend(self._compilation_verbosity_arg)

        if cmd_line_args:
            args += ["--"] + cmd_line_args

        arg_list = [f'"{bf}"', build_config, cmd_args_to_string(args)]
        arg_list = " ".join(filter(None, arg_list))
        command = "%s --build %s" % (self._cmake_program, arg_list)
        run(self._recipe, command, env=env, stdout=stdout, stderr=stderr)

    def build(
        self,
        build_type: str | None = None,
        target: str | list[str] | None = None,
        cli_args: list[str] | None = None,
        build_tool_args: list[str] | None = None,
        stdout: IO[Any] | None = None,
        stderr: IO[Any] | None = None,
        subfolder: str | None = None):
        """

        :param build_type: Use it only to override the value defined in the ``settings.build_type``
                           for a multi-configuration generator (e.g. Visual Studio, XCode).
                           This value will be ignored for single-configuration generators, they will
                           use the one defined in the toolchain file during the install step.
        :param target: The name of a single build target as a string, or names of multiple build
                       targets in a list of strings to be passed to the ``--target`` argument.
        :param cli_args: A list of arguments ``[arg1, arg2, ...]`` that will be passed to the
                         ``cmake --build ... arg1 arg2`` command directly.
        :param build_tool_args: A list of arguments ``[barg1, barg2, ...]`` for the underlying
                                build system that will be passed to the command
                                line after the ``--`` indicator: ``cmake --build ... -- barg1 barg2``
        :param subfolder: (Experimental): subfolder to be created inside the ``build_folder`` and
                                          the ``package_folder``. If not provided, files will be
                                          placed in the ``build_folder`` and ``package_folder`` root.
        :param stdout: Use it to redirect stdout to this stream
        :param stderr: Use it to redirect stderr to this stream
        """
        self._recipe.output.info("Running CMake.build()")
        self._build(
            build_type, target, cli_args, build_tool_args, subfolder=subfolder, stdout=stdout, stderr=stderr)

    def install(
        self, build_type: str | None = None, component: str | None = None, cli_args: list[str] | None = None, stdout: IO[Any] | None = None, stderr: IO[Any] | None = None, subfolder: str | None = None):
        """
        Equivalent to running ``cmake --install``

        :param component: The specific component to install, if any
        :param build_type: Use it only to override the value defined in the settings.build_type.
                           It can fail if the build is single configuration (e.g. Unix Makefiles),
                           as in that case the build type must be specified at configure time,
                           not build type.
        :param cli_args: A list of arguments ``[arg1, arg2, ...]`` for the underlying build system
                         that will be passed to the command line: ``cmake --install ... arg1 arg2``
        :param subfolder: (Experimental): subfolder to be created inside the ``build_folder`` and
                                          the ``package_folder``. If not provided, files will be
                                          placed in the ``build_folder`` and ``package_folder`` root.
        :param stdout: Use it to redirect stdout to this stream
        :param stderr: Use it to redirect stderr to this stream
        """
        self._recipe.output.info("Running CMake.install()")
        package_folder = self._recipe.folders.package
        build_folder = self._recipe.folders.build
        if subfolder:
            package_folder = package_folder / subfolder
            build_folder = build_folder / subfolder
        mkdir(self._recipe, package_folder)

        build_config = self._config_arg(build_type)

        pkg_folder = f'"{package_folder.as_posix()}"'
        build_folder = f'"{build_folder.as_posix()}"'
        arg_list = ["--install", build_folder, build_config, "--prefix", pkg_folder]
        if component:
            arg_list.extend(["--component", component])
        arg_list.extend(self._compilation_verbosity_arg)

        install_strip = self._recipe.conf.tools.build.install_strip
        do_strip = install_strip if isinstance(install_strip, bool) else "cmake" in (install_strip or [])
        if do_strip:
            arg_list.append("--strip")

        if cli_args:
            if "--install" in cli_args:
                raise RecipeException("Do not pass '--install' argument to 'install()'")
            arg_list.extend(cli_args)

        arg_list = " ".join(filter(None, arg_list))
        command = "%s %s" % (self._cmake_program, arg_list)
        run(self._recipe, command, stdout=stdout, stderr=stderr)

    def test(
        self,
        build_type: str | None = None,
        target: str | list[str] | None = None,
        cli_args: list[str] | None = None,
        build_tool_args: list[str] | None = None,
        env: str | list[str] = "",
        stdout: IO[Any] | None = None,
        stderr: IO[Any] | None = None):
        """
        Equivalent to running cmake --build . --target=RUN_TESTS.

        :param build_type: Use it only to override the value defined in the ``settings.build_type``.
                           It can fail if the build is single configuration (e.g. Unix Makefiles), as
                           in that case the build type must be specified at configure time, not build
                           time.
        :param target: Name of the build target to run, by default ``RUN_TESTS`` or ``test``
        :param cli_args: Same as above ``build()``, a list of arguments ``[arg1, arg2, ...]``
                         to be passed as extra arguments for the underlying build system
        :param build_tool_args: Same as above ``build()``
        :param stdout: Use it to redirect stdout to this stream
        :param stderr: Use it to redirect stderr to this stream
        """
        if self._recipe.conf.tools.build.skip_test:
            return
        if not target:
            is_multi = is_multi_configuration(self._generator)
            is_ninja = "Ninja" in (self._generator or "")
            target = "RUN_TESTS" if is_multi and not is_ninja else "test"

        # CTest behavior controlled by CTEST_ env-vars should be directly defined in [buildenv]
        # The default for ``test()`` is both the buildenv and the runenv
        env = ["env_build", "env_run"] if env == "" else env
        self._build(
            build_type=build_type, target=target, cli_args=cli_args, build_tool_args=build_tool_args, env=env, stdout=stdout, stderr=stderr)

    def ctest(
        self, cli_args: list[str] | None = None, env: str | list[str] = "", stdout: IO[Any] | None = None, stderr: IO[Any] | None = None):
        """
        Equivalent to running ctest ...

        :param cli_args: List of arguments ``[arg1, arg2, ...]`` to be passed as extra ctest
                         command line arguments
        :param env: the environment files to activate, by default buildenv + runenv
        :param stdout: Use it to redirect stdout to this stream
        :param stderr: Use it to redirect stderr to this stream
        """
        if self._recipe.conf.tools.build.skip_test:
            return

        arg_list: list[str] = []
        bt = self._recipe.settings.build_type
        is_multi = is_multi_configuration(self._generator)
        if bt and is_multi:
            arg_list.append(f"--build-config {bt}")
        njobs = build_jobs(self._recipe)
        if njobs:
            arg_list.append(f"--parallel {njobs}")

        arg_list.extend(cli_args or [])

        if self._recipe.conf.tools.build.verbose:
            # https://cmake.org/cmake/help/latest/manual/ctest.1.html
            # Options such as --verbose, --extra-verbose, and --debug are
            # ignored if --quiet is specified.
            arg_list.append("--verbose")

        extra_args = self._recipe.conf.tools.cmake.ctest_args
        if extra_args:
            arg_list.extend(extra_args)

        arg_str = " ".join(filter(None, arg_list))
        command = f"ctest {arg_str}"

        env = ["env_build", "env_run"] if env == "" else env
        run(self._recipe, command, env=env, stdout=stdout, stderr=stderr)

    @property
    def _compilation_verbosity_arg(self):
        """
        Controls build tool verbosity, that is, those controlled by -DCMAKE_VERBOSE_MAKEFILE
        See https://cmake.org/cmake/help/latest/manual/cmake.1.html#cmdoption-cmake-build-v
        """
        return ["--verbose"] if self._recipe.conf.tools.compilation.verbose else []

    @property
    def _cmake_log_levels_args(self):
        """
        Controls CMake's own verbosity levels.
        See https://cmake.org/cmake/help/latest/manual/cmake.1.html#cmdoption-cmake-log-level
        :return:
        """
        log_level = "VERBOSE" if self._recipe.conf.tools.build.verbose else "ERROR"
        return ["--loglevel=" + log_level]
